h the identical confirmed product, amount and date. Do not claim success.'\n    else:\n        p['state'] = 'note'\n        p['reason'] = 'service_error'\n        vars['promise_write_state'] = 'exhausted'\n        instruction = 'Say that the promise for ' + str(p.get('label', 'the affected product')) + ' could not be recorded. Do not retry it again. Keep all successful promises.'\n    pending = [q for q in rows if q.get('state') == 'pending']\n    if p and vars['promise_write_state'] in ['succeeded', 'already_recorded', 'exhausted']:\n        instruction += ' Immediately call create_promise for the next confirmed pending product shown in remaining_promises.' if pending else ' Proceed to final reconciliation; do not repeat successful writes. Defer all required notes until final non-transfer resolution.'\n    if p and not any(q.get('state') in ['open', 'pending'] for q in rows):\n        vars['resolution_ready'] = 'yes'\n    vars['product_state'] = rows\n    vars['recorded_promises'] = records\n    vars['product_facts'] = json.dumps(rows)\n    vars['pending_facts'] = json.dumps([q for q in rows if q.get('state') in ['pending', 'recorded']])\n    d['remaining_promises'] = pending\n    d['what_to_do_next'] = instruction\n    d['write_route'] = vars['resolution_ready']\nexcept Exception:\n    vars['resolution_ready'] = 'no'\n    vars['promise_write_state'] = 'failed'\n    vars['operational_hold'] = 'Promise result could not be reconciled.'\n    if isinstance(result, dict):\n        result.pop('header', None)\n        result.pop('headers', None)\n        result['data'] = dict(write_route='no', what_to_do_next='Explain that the promise result cannot be confirmed. Do not claim recording or retry blindly.')\n"
