r('Requested transfer has not succeeded; no notes permitted')\n    else:\n        if vars.get('security_state') != 'verified' or not isinstance(rows, list) or not rows:\n            raise ValueError('No verified resolved account')\n        recorded_ids = [str(p.get('product_id', '')) for p in recorded if isinstance(p, dict)]\n        dispositions = []\n        failures = []\n        for p in rows:\n            pid = str(p.get('product_id', ''))\n            if pid in recorded_ids:\n                continue\n            r = str(p.get('reason', ''))\n            if p.get('state') != 'note' or r not in ['refused', 'hardship', 'dispute', 'paid', 'service_error']:\n                raise ValueError('Unresolved product')\n            item = dict(product_id=pid, reason=r)\n            dispositions.append(item)\n            if r == 'service_error':\n                failures.append(str(p.get('label', 'the affected product')))\n            if not any(n.get('product_id') == pid and n.get('reason') == r for n in notes if isinstance(n, dict)):\n                needed.append(item)\n        if recorded_ids:\n            outcome = 'promise'\n            instruction = 'Confirm only actually recorded promises. If not yet spoken after the last success, say You will receive a text message confirming this promise.'\n        elif dispositions and all(p['reason'] == 'paid' for p in dispositions):\n            outcome = 'paid'\n            instruction = 'Explain, if not already explained, that payments can take one business day to appear.'\n        else:\n            outcome = 'no_promise'\n            reason = next(p['reason'] for p in dispositions if p['reason'] != 'paid')\n            instruction = 'Do not claim an unrecorded promise.'\n        for label in failures:\n            instruction += ' If not already said, explain that the promise for ' + label + ' could not be recorded.'\n    vars['close_outcome'] = outcome\n    vars['close_reason'] = reason\n    vars['notes_needed'] = needed